package com.procurement.goodsreceipt.controller;import com.procurement.common.response.*;import com.procurement.goodsreceipt.dto.request.*;import com.procurement.goodsreceipt.dto.response.*;import com.procurement.goodsreceipt.entity.*;import com.procurement.goodsreceipt.service.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/goods-receipts")public class GoodsReceiptController{private final GoodsReceiptService s;public GoodsReceiptController(GoodsReceiptService s){this.s=s;}@PostMapping public ResponseEntity<ApiResponse<GrnResponse>>create(@Valid@RequestBody GrnRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("GRN created",s.create(r)));}@GetMapping public ApiResponse<PageResponse<GrnResponse>>search(@RequestParam(required=false)Long purchaseOrderId,@RequestParam(required=false)GrnStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.search(purchaseOrderId,status,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"receiptDate"))));}@GetMapping("/{id}")public ApiResponse<GrnResponse>get(@PathVariable Long id){return ApiResponse.success(s.get(id));}@PostMapping("/{id}/lines")public ResponseEntity<ApiResponse<GrnLineResponse>>line(@PathVariable Long id,@Valid@RequestBody GrnLineRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("GRN line added",s.addLine(id,r)));}@GetMapping("/{id}/lines")public ApiResponse<PageResponse<GrnLineResponse>>lines(@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.lines(id,PageRequest.of(page,size)));}@PostMapping("/{id}/complete")public ApiResponse<GrnResponse>complete(@PathVariable Long id){return ApiResponse.success("GRN completed",s.complete(id));}}
